// @generated by:gauntlet run:godseye-local-hermes-chat
import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION } from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { chatFrames } from "./helpers/agents-chat-stream.js";
import { AgentProviderFixture } from "./helpers/agents-fixture.js";
import { owner, projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("real owner authentication for chat streams and downloads", () => {
  let f: OwnerAuthFixture;
  let engine: InfrastructureEngine;
  let provider: AgentProviderFixture;
  let headers: Headers;
  let app: ReturnType<typeof createApp>;
  beforeEach(async () => {
    f = await ownerAuthFixture();
    headers = (await f.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
    provider = new AgentProviderFixture();
    engine = new InfrastructureEngine(f.store, { agents: { provider, pollMs: 1 } });
    app = createApp(
      f.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      f.identity,
      engine.foundation,
      undefined,
      engine,
    );
  });
  afterEach(async () => {
    await f.close();
  });
  async function conversation() {
    const project = await f.core.createProject(owner, projectInput, randomUUID());
    const environment = project.environments.find((value) => value.kind === "development");
    if (!environment) throw new Error("Missing HTTP chat environment");
    const actor = await f.identity.actor(headers);
    if (!actor) throw new Error("Expected actual owner session");
    await engine.foundation.configureBudget(
      actor,
      project.id,
      { limitMicros: 100000, expectedRevision: 0 },
      randomUUID(),
    );
    const profile = await engine.agents.createProfile(
      actor,
      {
        projectId: project.id,
        environmentId: environment.id,
        expectedProjectRevision: project.revision,
        expectedEnvironmentRevision: environment.revision,
        role: "operations",
        model: "gpt-6-luna",
        limits: {
          maxOutputTokens: 1024,
          timeoutSeconds: 5,
          maxCostMicros: 10000,
          maxTurns: 1,
          maxRequests: 1,
        },
      },
      randomUUID(),
    );
    const detail = await engine.agents.chatCreate(
      actor,
      { profileId: profile.id, expectedRevision: profile.revision, title: "Private HTTP chat" },
      randomUUID(),
    );
    return { actor, detail, id: detail.conversation.id };
  }

  it("T-AC-751 authenticates every new route before processing caller input", async () => {
    for (const [method, path] of [
      ["GET", "/conversations"],
      ["POST", "/conversations"],
      ["GET", `/conversations/${randomUUID()}`],
      ["POST", `/conversations/${randomUUID()}/turns`],
      ["GET", `/conversations/${randomUUID()}/events`],
      ["GET", `/artifacts/${randomUUID()}/download`],
      ["POST", `/proposals/${randomUUID()}/resolve`],
    ] as const) {
      const response = await app.request(new URL(`/api/v1/agents${path}`, f.origin), {
        method,
        headers: f.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });

  it("T-AC-745 revalidates the actual owner session and closes a waiting SSE reader after revocation", async () => {
    const { id, actor } = await conversation();
    const response = await app.request(
      new URL(`/api/v1/agents/conversations/${id}/events`, f.origin),
      { headers },
    );
    expect(response.status).toBe(200);
    if (!response.body) throw new Error("Expected owner-authenticated stream");
    const stream = chatFrames(response.body);
    try {
      expect((await stream.next())?.event).toBe("ready");
      await f.store.db
        .update(schema.ownerSession)
        .set({ expiresAt: new Date(0) })
        .where(eq(schema.ownerSession.id, actor.sessionId ?? "missing"));
      expect(await stream.next()).toBeNull();
      expect(provider.submissions).toHaveLength(0);
      expect(provider.stops).toHaveLength(0);
    } finally {
      await stream.reader.cancel();
    }
  });

  it("T-AC-747 returns immutable UTF-8 draft bytes as private inert attachments", async () => {
    const { id, actor, detail } = await conversation();
    const content = "<script>globalThis.__chatXss=true</script>\nRésumé 😀";
    provider.inspectScript = async (request) => ({
      state: "succeeded",
      providerRunId: request.providerRunId,
      stopped: true,
      output:
        "```godseye-output-v1\n" +
        JSON.stringify({
          type: "artifact",
          name: "draft.md",
          mediaType: "text/markdown",
          content,
        }) +
        "\n```",
    });
    await engine.agents.chatSend(
      actor,
      id,
      { input: "Draft an inert attachment", expectedRevision: detail.conversation.revision },
      randomUUID(),
    );
    await engine.foundation.tick("http-chat-fixture-worker");
    const artifact = (await engine.agents.chatDetail(actor, id)).artifacts[0];
    if (!artifact) throw new Error("Expected actual persisted draft artifact");
    const response = await app.request(
      new URL(`/api/v1/agents/artifacts/${artifact.id}/download`, f.origin),
      { headers },
    );
    expect(response.status).toBe(200);
    expect(await response.text()).toBe(content);
    expect(response.headers.get("content-type")).toBe("text/plain; charset=utf-8");
    expect(response.headers.get("content-disposition")).toBe(
      `attachment; filename="artifact-${artifact.id}.txt"`,
    );
    expect(response.headers.get("x-content-type-options")).toBe("nosniff");
    expect(response.headers.get("cache-control")).toBe("private, no-store");
    expect(response.headers.get("content-security-policy")).toContain("sandbox");
  });

  it("T-AC-751 refuses unknown authority fields in conversation and proposal requests", async () => {
    const { id, detail } = await conversation();
    const response = await app.request(
      new URL(`/api/v1/agents/conversations/${id}/turns`, f.origin),
      {
        method: "POST",
        headers: new Headers([...headers, ["idempotency-key", randomUUID()]]),
        body: JSON.stringify({
          input: "No endpoint authority",
          expectedRevision: detail.conversation.revision,
          endpoint: "http://127.0.0.1/private",
        }),
      },
    );
    expect(response.status).toBe(422);
    expect(provider.submissions).toHaveLength(0);
    const actor = await f.identity.actor(headers);
    if (!actor) throw new Error("Expected actual owner session");
    expect((await engine.agents.chatDetail(actor, id)).turns).toEqual([]);
  });
});
